CREATE TABLE `tema_coment` (
  `Codtema_coment` int(11) NOT NULL AUTO_INCREMENT,
  `Tema` int(11) DEFAULT NULL,
  `Coment` int(11) DEFAULT NULL,
  `Data` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Data de registro',
  PRIMARY KEY (`Codtema_coment`),
  UNIQUE KEY `SECONDARY` (`Tema`,`Coment`),
  KEY `fk2` (`Coment`),
  CONSTRAINT `fk1` FOREIGN KEY (`Tema`) REFERENCES `tema` (`Codtema`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk2` FOREIGN KEY (`Coment`) REFERENCES `coment` (`Codcoment`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1592 DEFAULT CHARSET=utf8mb4;
